functions.sha1:
int sha1(uint8_t *buf, size_t len, size_t cap, uint8_t hash[20])
{
    static const uint32_t k[] = {0x5A827999, 0x6ED9EBA1, 0x8F1BBCDC, 0xCA62C1D6};
    size_t new_len, i, t;
    uint32_t h[5], w[80];
    uint32_t a, b, c, d, e, f, T;
    if (len > (18446744073709551615UL) - 9 - 63)
        return TOTP_EBOUNDS;
    new_len = (len + 9 + 63) / 64 * 64;
    if (new_len > cap)
        return TOTP_EBOUNDS;
    memset(buf + len, 0, new_len - len);
    buf[len] = 1 << 7;
    unpack64(len * 8, &buf[new_len - 8]);
    h[0] = 0x67452301;
    h[1] = 0xEFCDAB89;
    h[2] = 0x98BADCFE;
    h[3] = 0x10325476;
    h[4] = 0xC3D2E1F0;
    for (i = 0; i < new_len / 64; i++)
    {
        for (t = 0; t < 16; t++)
            w[t] = pack32(&buf[i * 64 + t * 4]);
        for (; t < 80; t++)
            w[t] = rotl(w[t - 3] ^ w[t - 8] ^ w[t - 14] ^ w[t - 16], 1);
        a = h[0];
        b = h[1];
        c = h[2];
        d = h[3];
        e = h[4];
        for (t = 0; t < 80; t++)
        {
            f = t < 20 ? (b & c) ^ (~b & d) : t < 40 ? b ^ c ^ d : t < 60 ? (b & c) ^ (b & d) ^ (c & d) : b ^ c ^ d;
            T = rotl(a, 5) + f + e + k[t / 20] + w[t];
            e = d;
            d = c;
            c = rotl(b, 30);
            b = a;
            a = T;
        }
        h[0] += a;
        h[1] += b;
        h[2] += c;
        h[3] += d;
        h[4] += e;
    }
    for (i = 0; i < 5; i++)
        unpack32(h[i], &hash[i * 4]);
    return TOTP_OK;
}

functions.hmac_sha1:
int hmac_sha1(const uint8_t key[64], const uint8_t *data, size_t len, uint8_t hash[20])
{
    uint8_t buf[196];
    size_t i;
    if (len > 64)
        return TOTP_EBOUNDS;
    for (i = 0; i < 64; i++)
        buf[i] = key[i] ^ 0x36;
    memcpy(&buf[64], data, len);
    sha1(buf, 64 + len, sizeof(buf), hash);
    for (i = 0; i < 64; i++)
        buf[i] = key[i] ^ 0x5C;
    memcpy(&buf[64], hash, 20);
    sha1(buf, 64 + 20, sizeof(buf), hash);
    return TOTP_OK;
}

functions.hotp:
int hotp(const uint8_t key[64], uint64_t counter)
{
    uint8_t data[8], hash[20];
    uint32_t trunc;
    unpack64(counter, data);
    hmac_sha1(key, data, 8, hash);
    trunc = pack32(&hash[hash[19] & 0xF]) & 0x7FFFFFFF;
    return (int)(trunc % 1000000);
}

functions.totp:
int totp(const uint8_t key[64], uint64_t time)
{
    return hotp(key, time / 30);
}

